-- SINH RA boi tools/pokemon/sinh_noi_dung.py - KHONG SUA TAY.
-- Noi dung day du 1-2 nam (docs/pokemon/NOI_DUNG_DAY_DU.md). SQL portable (MySQL/MariaDB/NovaDB):
-- chay lai nhieu lan van cho cung ket qua. Gom vao tools/pokemon/xuat_sql_day_du.sh (sau LAU_DAI).
-- PHAN A: bang staging data_noi_dung_* (so lieu thiet ke; giai doan 2/3 doc). Khong doi bang dang chay.
-- PHAN B: data_item id 1001..1199 (trang bi bac than thoai/toi thuong, ruy bang bac thap,
--         nguyen lieu, vat pham su kien/dot kich). Server nap luc khoi dong (Map.loadAllTemplate)
--         va gui xuong client (MessageCreator: gui du id 0..max). Chua co nguon roi/ban nao tro toi
--         khi sv.lau_dai=0 nen KHONG doi hanh vi game cu.
SET NAMES utf8;

DROP TABLE IF EXISTS `data_noi_dung_trang_bi`;
CREATE TABLE `data_noi_dung_trang_bi` (
  `ma` varchar(255) NOT NULL,
  `bac` bigint NOT NULL,
  `ten_bac` varchar(255) NOT NULL,
  `o` varchar(255) NOT NULL,
  `type_item` bigint NOT NULL,
  `dong` varchar(255) NOT NULL,
  `ten` varchar(255) NOT NULL,
  `id_item` bigint NOT NULL,
  `trang_thai` varchar(255) NOT NULL,
  `cap_yeu_cau` bigint NOT NULL,
  `cap_item` bigint NOT NULL,
  `ngay_mo` bigint NOT NULL,
  `tran_cap_khi_mo` bigint NOT NULL,
  `so_o` bigint NOT NULL,
  `tan_cong` bigint NOT NULL,
  `phong_thu` bigint NOT NULL,
  `hp` bigint NOT NULL,
  `chi_so_phu` varchar(255) NOT NULL,
  `he` varchar(255) NOT NULL,
  `gia_xu` bigint NOT NULL,
  `ban_npc_xu` bigint NOT NULL,
  `phan_ra` varchar(255) NOT NULL,
  `nguon` varchar(255) NOT NULL,
  `ghi_chu` varchar(255) NOT NULL,
  PRIMARY KEY (`ma`)
) DEFAULT CHARSET=utf8;
