('bui_sao','Bụi sao','nguyen_lieu_phu','item:1034','Nâng cấp +11 đến +15 cho đồ bậc sơ cấp, đồng, bạc (1 cái mỗi lần thử)','quái ở dải cấp của bậc rơi (0,4%), phân rã đồ bậc đó, chế tạo',0,'khong_ban'),
('manh_sao','Mảnh sao','nguyen_lieu_phu','item:1035','Nâng cấp +11 đến +15 cho đồ bậc vàng, bạch kim, kim cương (1 cái mỗi lần thử)','quái ở dải cấp của bậc rơi (0,4%), phân rã đồ bậc đó, chế tạo',0,'khong_ban'),
('manh_thien_thach','Mảnh thiên thạch','nguyen_lieu_phu','item:1036','Nâng cấp +11 đến +15 cho đồ bậc chuyên gia, tinh anh, huyền thoại (1 cái mỗi lần thử)','quái ở dải cấp của bậc rơi (0,4%), phân rã đồ bậc đó, chế tạo',0,'khong_ban'),
('vay_rong','Vảy rồng','nguyen_lieu_phu','item:1037','Nâng cấp +11 đến +15 cho đồ bậc thần thoại, tối thượng (1 cái mỗi lần thử)','quái ở dải cấp của bậc rơi (0,4%), phân rã đồ bậc đó, chế tạo',0,'khong_ban'),
