('da_nang_cap','Đá nâng cấp','nguyen_lieu_chinh','ngoc:8','Mọi lần nâng cấp: lên +1 đến +5 cần 1 viên, +6 đến +10 cần 2 viên, +11 đến +15 cần 4 viên','quái chênh tối đa 5 cấp rơi 1,5%, quái tinh anh chắc chắn rơi, phân rã 1 món được 2 viên',0,'khong_ban'),
